#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Deploys #29 provisioning: SSH deploy key on the homelab server, server-side
# GHCR login, and the GitHub secrets/variables the Image workflow's deploy job
# reads. Values are never written to the repo; ENV_FILE lives in /tmp.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1 && tput clear 2>/dev/null; then return 0; fi
  printf '\033[2J\033[3J\033[H'
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else false; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any, with write_env's single
# quotes or a plain dotenv double-quoted value undone.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line value sq="'\\''"; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  value="${line#*=}"
  if [[ "$value" == \'*\' ]]; then value="${value:1:${#value}-2}"; value="${value//"$sq"/\'}"
  elif [[ "$value" == \"*\" ]]; then
    value="${value:1:${#value}-2}"
    [[ "$value" == *[\\\$\"]* ]] && return 1   # escapes, $ or ": can't decode safely; ask again
  fi
  printf '%s' "$value"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret), edited
# with Readline. Fails at EOF with no input.
ask() {
  local key="$1" prompt="$2" current input s=$'\001' e=$'\002' p rc=0
  current=$(_existing "$key" || true)
  # Readline needs the colour codes wrapped in \001..\002 to place the cursor.
  p="  $s$BOLD$e$prompt$s$RESET$e "
  [[ -n "$current" ]] && p+="${s}${DIM}${e}[Enter keeps current]${s}${RESET}${e} "
  read -e -r -p "$p" input || rc=1
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input rc=0
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || rc=1
  printf '\n'
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY='VALUE' into ENV_FILE (replaces any existing
# line) and sets $KEY. Idempotent. Creates ENV_FILE at mode 0600; writes through
# a symlink and keeps an existing file's mode.
write_env() {
  local key="$1" value="$2" tmp sq="'\\''"
  [[ -e "$ENV_FILE" ]] || (umask 077 && : > "$ENV_FILE")
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf "%s='%s'\n" "$key" "${value//\'/$sq}" >> "$tmp"
  cat "$tmp" > "$ENV_FILE"
  rm -f "$tmp"
  printf -v "$key" '%s' "$value"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# Keep every stage inside run_wizard and the last line as is: bash then parses
# the whole file before the first prompt, so an edit mid-run can't break it.
# ──────────────────────────────────────────────────────────────────────────

run_wizard() {

TOTAL_STAGES=7
ENV_FILE="${ENV_FILE:-/tmp/wortschatz-deploy-wizard.env}"
REPO="${REPO:-thom404/wortschatz}"
DEFAULT_DEPLOY="$HOME/Docker/production/wordament"
KEY_FILE=""

banner "Homelab auto-deploy provisioning (#29)"

stage "Server coordinates"
say "The deploy job SSHes into the homelab to re-pin the compose image, pull and restart."
ask SSH_USER "Deploy SSH user on the server (in the docker group):"
ask SSH_HOST "Server host or host:port (e.g. 192.168.1.10:2222):"
ask DEPLOY_DIR "Compose dir on the server [Enter = default]:"
write_env SSH_USER "$SSH_USER"
write_env SSH_HOST "$SSH_HOST"
if [[ -n "$DEPLOY_DIR" ]]; then
  write_env DEPLOY_DIR "$DEPLOY_DIR"
fi

stage "Probe your server access"
HOST="${SSH_HOST%%:*}"
PORT="${SSH_HOST#*:}"
SSH_OPTS=(-o BatchMode=yes -o ConnectTimeout=10)
if [[ "$SSH_HOST" != "$HOST" ]]; then SSH_OPTS+=(-p "$PORT"); fi
while ! ssh "${SSH_OPTS[@]}" "$SSH_USER@$HOST" true 2>/dev/null; do
  warn "Passwordless SSH as $SSH_USER@$HOST fails with your normal key."
  step "Fix your own login first (ssh-copy-id, or enable that key in your agent)."
  note "docs: OPERATOR-STEPS.md §7"
  pause "[Enter] retry · Ctrl-C stop"
done
say "✓ your normal key reaches $HOST non-interactively."
# shellcheck disable=SC2029  # client-side expansion is intended here
if ssh "${SSH_OPTS[@]}" "$SSH_USER@$HOST" "test -f '${DEPLOY_DIR:-$DEFAULT_DEPLOY}/compose.yaml'"; then
  say "✓ compose.yaml already sits in the deploy directory (from the #33 rollout)."
else
  warn "compose.yaml NOT found in '${DEPLOY_DIR:-$DEFAULT_DEPLOY}' on the server."
  step "Stage it per OPERATOR-STEPS.md §3 before merging #29's PR."
  pause "Confirm:"
fi

stage "Generate the deploy key"
say "One dedicated key pair, used only by CI to reach this box (no passphrase)."
ask KEY_FILE "Key file path (Enter = ~/.ssh/wortschatz_deploy):"
DEFAULT_KEY="$HOME/.ssh/wortschatz_deploy"
KEY_FILE="${KEY_FILE:-$DEFAULT_KEY}"
if [[ -f "$KEY_FILE" ]]; then
  say "✓ reusing existing key $KEY_FILE."
else
  ssh-keygen -t ed25519 -f "$KEY_FILE" -N "" -C "wortschatz ci deploy"
  say "✓ generated $KEY_FILE(.pub)."
fi
chmod 600 "$KEY_FILE"

stage "Install the public key on the server"
PUB="${KEY_FILE}.pub"
if ssh "${SSH_OPTS[@]}" "$SSH_USER@$HOST" \
     "mkdir -p ~/.ssh && chmod 700 ~/.ssh && cat >> ~/.ssh/authorized_keys && chmod 600 ~/.ssh/authorized_keys" \
     < "$PUB" 2>/dev/null; then
  say "✓ installed $PUB into authorized_keys."
else
  warn "auto-install failed; append by hand:"
  step "  printf 'key' | ssh $SSH_USER@$HOST 'mkdir -p ~/.ssh && cat >> ~/.ssh/authorized_keys && chmod 600 ~/.ssh/authorized_keys'"
  pause "Press Enter once done."
fi

stage "Validate key login + host fingerprints"
if ssh -i "$KEY_FILE" -o BatchMode=yes -o StrictHostKeyChecking=accept-new \
      "${SSH_OPTS[@]}" "$SSH_USER@$HOST" true 2>/dev/null; then
  say "✓ deploy key authenticates without password or host prompt."
else
  warn "deploy-key login rejected; check ~/.ssh/authorized_keys on the server, then:"
  pause "[Enter] recheck · Ctrl-C abort"
  ssh -i "$KEY_FILE" -o BatchMode=yes "${SSH_OPTS[@]}" "$SSH_USER@$HOST" true
fi
SCAN_ARGS=(-t ed25519 -T 10)
if [[ "$SSH_HOST" != "$HOST" ]]; then SCAN_ARGS+=(-p "$PORT"); fi
SCAN=$(ssh-keyscan "${SCAN_ARGS[@]}" "$HOST" 2>/dev/null || true)
if [[ -n "$SCAN" ]]; then
  say "✓ ssh-keyscan fetched the host key fingerprint."
  set_secret SSH_KNOWN_HOSTS "$SCAN"
else
  warn "ssh-keyscan produced no host key; SSH_KNOWN_HOSTS stays unset."
fi

stage "Server-side GHCR docker login (optional)"
say "The image is public since ADR-0004: anonymous pulls already work on the server."
say "A read-only PAT keeps the flow working if the repo ever turns private again."
open_url "https://github.com/settings/tokens/new?scopes=read:packages&description=wortschatz%20homelab%20ro%20pull"
if confirm "Create a read:packages token and docker-login the server now?"; then
  ask_secret GHCR_READ_TOKEN "Paste the read:packages token (input hidden):"
  if ssh "${SSH_OPTS[@]}" "$SSH_USER@$HOST" "docker login ghcr.io --password-stdin" <<< "${GHCR_READ_TOKEN}" 2>/dev/null; then
    say "✓ server docker login ghcr.io ok (read-only)."
  else
    warn "docker login failed over ssh; run it manually on the server:"
    step "  docker login ghcr.io --password-stdin   (then paste the token)"
    pause "Press Enter when done."
  fi
fi

stage "Commit the values to GitHub"
say "These become repo Actions secrets + one optional repo variable; nothing is committed to git."
gh_ok() { command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; }
while ! gh_ok; do
  warn "gh CLI unavailable/unauthenticated (needs repo access to $REPO)."
  step "gh auth login, then [Enter] to retry · Ctrl-C to skip and finish."
  pause "check:"
done
set_secret SSH_PRIVATE_KEY "$(cat "$KEY_FILE")"
set_secret SSH_USER "$SSH_USER"
set_secret SSH_HOST "$SSH_HOST"
if [[ -n "$SCAN" ]]; then set_secret SSH_KNOWN_HOSTS "$SCAN"; fi
if [[ -n "${DEPLOY_DIR:-}" ]]; then set_var DEPLOY_DIR "$DEPLOY_DIR"; fi
if confirm "Provisioning done — trigger a deploy right now (gh workflow run Image)?"; then
  if gh workflow run Image --repo "$REPO" 2>/dev/null; then
    say "✓ Image workflow queued (build + deploy)."
    step "gh run watch --repo $REPO"
    open_url "https://github.com/$REPO/actions/workflows/image.yml"
  else
    warn "couldn't queue a run; it fires anyway on the next merge to main."
  fi
fi

finish
}

run_wizard "$@"; exit
